import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  fmtNum,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 960;
const CX = W / 2;

const COLORS = {
  img: { fill: '#e8f5e9', stroke: '#4caf50' },
  patch: { fill: '#e3f2fd', stroke: '#1976d2' },
  code: { fill: '#fff3e0', stroke: '#e65100' },
  quant: { fill: '#fce4ec', stroke: '#c62828' },
  book: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  out: { fill: '#e8f5e9', stroke: '#2e7d32' },
  weight: { fill: '#f1f8e8', stroke: '#64748b' },
  text: 'var(--text)' as string,
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 72;
const MAT_H = 80;
const SEQ_W = 200;
const BOX_TO_ROW = 90;
const ROW_GAP = 64;
const STEP_GAP = 76;
const WEIGHT_W = 150;
const WEIGHT_H = 80;

interface TokStep extends StepInfo {}

function lbl(g: Gsel, x: number, y: number, text: string, opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}): void {
  drawLabel(g as Sel, x, y, text, opts);
}
function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void { drawArrow(g as Sel, x, y1, x, y2, { color }); }
function startGroup(g: Gsel, cls: string, step: number): Gsel { return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step)); }

function stepHeader(g: Gsel, cx: number, y: number, sn: number, title: string, formula: string, fill: string, stroke: string, width = 760): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H).attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 24).attr('cy', y + BOX_H / 2).attr('r', 14).attr('fill', stroke);
  lbl(g, cx - w / 2 + 24, y + BOX_H / 2 + 1, String(sn), { size: 12, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 48, y + BOX_H / 2 - 6, title, { size: 13, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 48, y + BOX_H / 2 + 10, formula, { size: 9, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function drawShapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.5 + 28, 180);
  const h = 28;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h).attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy, text, { size: 8.5, color, font: 'monospace' });
}

function drawSeqMatrix(g: Gsel, cx: number, cy: number, label: string, sub: string, fill: string, stroke: string, w = SEQ_W, h = MAT_H): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, { width: w, height: h, label, sublabel: sub, fill, stroke, cols: 8, rows: 5, dimTop: 'P', dimRight: 'D' });
}

function drawWeight(g: Gsel, cx: number, cy: number, label: string, sub: string, fill = COLORS.weight.fill, stroke = COLORS.weight.stroke, w = WEIGHT_W, h = WEIGHT_H): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, { width: w, height: h, label, sublabel: sub, fill, stroke, cols: 5, rows: 5 });
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 18).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 14, weight: '700', color });
}

function drawParamSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 160;
  const h = 34;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h).attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => { lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' }); });
  return y + h;
}

function makeStep(id: number, sl: string, l: string, f: string, ex: string, sg: string, c: string, fl: string, cl?: string[]): TokStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex, code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Image grid
// ═══════════════════════════════════════════════════════════════════════════════

function drawImageGrid(g: Gsel, cx: number, cy: number, patchSize: number, gridN: number, actualGridN: number, color: string): void {
  const totalW = 220;
  const totalH = 220;
  const gg = g.append('g').attr('transform', `translate(${cx - totalW / 2}, ${cy - totalH / 2})`);
  gg.append('rect').attr('width', totalW).attr('height', totalH).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.4);
  const cellW = totalW / gridN;
  const cellH = totalH / gridN;
  let seed = 42;
  const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
  for (let r = 0; r < gridN; r++) for (let c = 0; c < gridN; c++) {
    const v = 0.15 + lcg() * 0.55;
    gg.append('rect').attr('x', c * cellW + 0.5).attr('y', r * cellH + 0.5).attr('width', cellW - 1).attr('height', cellH - 1).attr('rx', 1).attr('fill', color).attr('opacity', v);
  }
  if (gridN <= 14) {
    for (let i = 1; i < gridN; i++) {
      gg.append('line').attr('x1', i * cellW).attr('y1', 0).attr('x2', i * cellW).attr('y2', totalH).attr('stroke', '#fff').attr('stroke-width', 0.3).attr('opacity', 0.5);
      gg.append('line').attr('x1', 0).attr('y1', i * cellH).attr('x2', totalW).attr('y2', i * cellH).attr('stroke', '#fff').attr('stroke-width', 0.3).attr('opacity', 0.5);
    }
  }
  lbl(g, cx - totalW / 2 - 8, cy, `${patchSize * actualGridN}×${patchSize * actualGridN}`, { size: 8, color: COLORS.muted, anchor: 'end' });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Discrete code strip
// ═══════════════════════════════════════════════════════════════════════════════

function drawCodeStrip(g: Gsel, cx: number, cy: number, nPatches: number, vocabSize: number, color: string): void {
  const stripW = 300;
  const stripH = 44;
  const gg = g.append('g').attr('transform', `translate(${cx - stripW / 2}, ${cy - stripH / 2})`);
  gg.append('rect').attr('width', stripW).attr('height', stripH).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 0.8).attr('opacity', 0.5);
  const nShow = Math.min(nPatches, 16);
  const cW = stripW / (nShow + 2);
  let seed = 777;
  const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
  for (let i = 0; i < nShow; i++) {
    const codeVal = Math.floor(lcg() * vocabSize);
    const hue = (codeVal / vocabSize) * 300;
    gg.append('rect').attr('x', i * cW + 2).attr('y', 4).attr('width', cW - 4).attr('height', stripH - 8).attr('rx', 2).attr('fill', `hsl(${hue}, 65%, 55%)`).attr('opacity', 0.8);
    if (cW > 14) {
      lbl(g, cx - stripW / 2 + i * cW + cW / 2, cy, String(codeVal), { size: 6, color: '#fff', weight: '600' });
    }
  }
  if (nShow < nPatches) {
    lbl(g, cx + stripW / 2 - 20, cy, '…', { size: 12, color });
  }
  lbl(g, cx, cy - stripH / 2 - 10, `${nPatches} discrete codes (each ∈ [0, ${fmtNum(vocabSize)})`, { size: 8.5, color: COLORS.muted });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Codebook table
// ═══════════════════════════════════════════════════════════════════════════════

function drawCodebook(g: Gsel, cx: number, cy: number, vocabSize: number, dModel: number, nPatches: number, color: string): void {
  const tblW = 380;
  const tblH = 160;
  const gg = g.append('g').attr('transform', `translate(${cx - tblW / 2}, ${cy - tblH / 2})`);

  gg.append('rect').attr('width', tblW).attr('height', tblH).attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 1.5);
  lbl(g, cx, cy - tblH / 2 + 14, `Codebook  [${fmtNum(vocabSize)}, ${dModel}]`, { size: 10, weight: '700', color });

  const headerY = cy - tblH / 2 + 30;
  gg.append('line').attr('x1', 8).attr('y1', headerY - 8).attr('x2', tblW - 8).attr('y2', headerY - 8).attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.4);
  lbl(g, cx - tblW / 2 + 50, headerY, 'index', { size: 8, color: COLORS.muted, weight: '600' });
  lbl(g, cx + 40, headerY, `embedding vector [${dModel}]`, { size: 8, color: COLORS.muted, weight: '600' });

  let seed = 123;
  const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
  const nShow = 5;
  const rowH = 18;
  const startRowY = headerY + 14;

  const selectedRows = new Set<number>();
  let seed2 = 456;
  const lcg2 = () => { seed2 = (seed2 * 1664525 + 1013904223) & 0xffffffff; return (seed2 >>> 0) / 0xffffffff; };
  for (let i = 0; i < Math.min(nPatches, 4); i++) { selectedRows.add(Math.floor(lcg2() * nShow)); }

  for (let r = 0; r < nShow; r++) {
    const ry = startRowY + r * rowH;
    const isSelected = selectedRows.has(r);
    if (isSelected) {
      gg.append('rect').attr('x', 4).attr('y', ry - rowH / 2).attr('width', tblW - 8).attr('height', rowH).attr('rx', 2).attr('fill', color).attr('opacity', 0.12);
    }
    lbl(g, cx - tblW / 2 + 50, ry, String(r), { size: 7.5, color: isSelected ? color : COLORS.muted, weight: isSelected ? '700' : '400' });
    const vecW = tblW - 130;
    const nCells = Math.min(12, Math.floor(vecW / 8));
    const cellW2 = vecW / nCells;
    for (let c = 0; c < nCells; c++) {
      const v = lcg();
      gg.append('rect').attr('x', cx - tblW / 2 + 90 + c * cellW2).attr('y', ry - rowH / 2 + 2).attr('width', cellW2 - 1).attr('height', rowH - 4).attr('rx', 1).attr('fill', color).attr('opacity', isSelected ? 0.15 + v * 0.5 : 0.05 + v * 0.15);
    }
  }
  lbl(g, cx, startRowY + nShow * rowH + 6, '⋮', { size: 14, color });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main pipeline
// ═══════════════════════════════════════════════════════════════════════════════

function renderPipeline(g: Gsel, startY: number, nPatches: number, dModel: number, vocabSize: number): { steps: TokStep[]; y: number } {
  const steps: TokStep[] = [];
  let stepId = 1;
  let y = startY;
  const patchSize = 16;
  const gridN = Math.round(Math.sqrt(nPatches));

  // ── Step 1: Input Image ──────────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-img', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Input Image', `image: [3, ${patchSize * gridN}, ${patchSize * gridN}]`, COLORS.img.fill, COLORS.img.stroke);
    arrowDown(gs, CX, y, h, COLORS.img.stroke);
    const imgCY = h + BOX_TO_ROW + 110;
    drawImageGrid(gs, CX, imgCY, patchSize, Math.min(gridN, 14), gridN, COLORS.img.stroke);
    lbl(gs, CX, imgCY + 110 + 18, `${patchSize * gridN}×${patchSize * gridN} RGB image`, { size: 9, color: COLORS.muted });
    steps.push(makeStep(stepId, 'Image', 'Input Image', `[3, ${patchSize * gridN}, ${patchSize * gridN}]`, `Input RGB image of resolution ${patchSize * gridN}×${patchSize * gridN} pixels with 3 color channels.`, 'step-img', COLORS.img.stroke, COLORS.img.fill));
    stepId++;
    y = imgCY + 110 + STEP_GAP;
  }

  // ── Step 2: Patchify (Conv) ──────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-patch', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Patchify (Conv16×16)', `patches = conv(image) → [${nPatches}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke);
    arrowDown(gs, CX, y, h, COLORS.patch.stroke);

    const rowY = h + BOX_TO_ROW + 70;
    // Small image
    const sgW = 110;
    const sgH = 110;
    const sgG = gs.append('g').attr('transform', `translate(${CX - 280 - sgW / 2}, ${rowY - sgH / 2})`);
    sgG.append('rect').attr('width', sgW).attr('height', sgH).attr('rx', 4).attr('fill', 'none').attr('stroke', COLORS.img.stroke).attr('stroke-width', 0.8);
    let seed = 99;
    const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
    const gn = Math.min(gridN, 7);
    const cW = sgW / gn;
    const cH = sgH / gn;
    for (let r = 0; r < gn; r++) for (let c = 0; c < gn; c++) {
      sgG.append('rect').attr('x', c * cW + 0.5).attr('y', r * cH + 0.5).attr('width', cW - 1).attr('height', cH - 1).attr('rx', 1).attr('fill', COLORS.img.stroke).attr('opacity', 0.15 + lcg() * 0.55);
    }
    lbl(gs, CX - 280, rowY - sgH / 2 - 12, 'image', { size: 8, color: COLORS.muted });

    // Arrow
    drawArrow(gs as Sel, CX - 280 + sgW / 2 + 4, rowY, CX - 100, rowY, { color: COLORS.patch.stroke });
    lbl(gs, CX - 190, rowY - 14, 'conv 16×16, stride 16', { size: 8, color: COLORS.muted });

    // Patch strip
    const stripW = 220;
    const stripH = 56;
    const stripG = gs.append('g').attr('transform', `translate(${CX + 60 - stripW / 2}, ${rowY - stripH / 2})`);
    stripG.append('rect').attr('width', stripW).attr('height', stripH).attr('rx', 4).attr('fill', 'none').attr('stroke', COLORS.patch.stroke).attr('stroke-width', 1).attr('opacity', 0.4);
    const nShow = Math.min(nPatches, 10);
    const pW = stripW / (nShow + 2);
    for (let i = 0; i < nShow; i++) {
      stripG.append('rect').attr('x', i * pW + 2).attr('y', 4).attr('width', pW - 4).attr('height', stripH - 8).attr('rx', 2).attr('fill', COLORS.patch.stroke).attr('opacity', 0.15 + lcg() * 0.55);
    }
    lbl(gs, CX + 60, rowY - stripH / 2 - 12, `${nPatches} patches`, { size: 8.5, color: COLORS.muted });
    lbl(gs, CX + 60, rowY + stripH / 2 + 14, `each: 16×16×3 → projected to ${dModel}`, { size: 8, color: COLORS.muted });

    // Output matrix
    const outY = rowY + stripH / 2 + ROW_GAP + MAT_H / 2;
    arrowDown(gs, CX, rowY + stripH / 2 + 20, outY - MAT_H / 2, COLORS.patch.stroke);
    drawSeqMatrix(gs, CX, outY, 'patches', `[${nPatches}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke);
    drawShapeEq(gs, CX, outY + MAT_H / 2 + 24, `conv16×16 stride16: image [3, ${patchSize * gridN}, ${patchSize * gridN}] → patches [${nPatches}, ${dModel}]`, COLORS.patch.stroke);
    steps.push(makeStep(stepId, 'Patchify', 'Patchify (Conv)', `conv → [${nPatches}, ${dModel}]`, 'Non-overlapping 16×16 convolution splits image into patches and projects each to d_model.', 'step-patch', COLORS.patch.stroke, COLORS.patch.fill, [
      `# Patchify: conv with kernel=patch_size, stride=patch_size`,
      `patchify = nn.Conv2d(3, ${dModel}, kernel_size=16, stride=16)`,
      `patches = patchify(image)  # [B, ${dModel}, ${gridN}, ${gridN}]`,
      `patches = patches.flatten(2).transpose(1,2)  # [B, ${nPatches}, ${dModel}]`,
    ]));
    stepId++;
    y = outY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 3: Code Logits (Linear Projection) ──────────────────────────────
  {
    const gs = startGroup(g, 'step-code', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Code Logits', `codes = patches · W_codes → [${nPatches}, ${fmtNum(vocabSize)}]`, COLORS.code.fill, COLORS.code.stroke);
    arrowDown(gs, CX, y, h, COLORS.code.stroke);

    const rowY = h + BOX_TO_ROW + MAT_H / 2;
    // Input patches
    drawSeqMatrix(gs, CX - 260, rowY, 'patches', `[${nPatches}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke, 170, MAT_H);
    // Multiply
    opCircle(gs, CX - 80, rowY, '×', COLORS.code.stroke);
    drawArrow(gs as Sel, CX - 260 + 85 + 4, rowY, CX - 80 - 20, rowY, { color: COLORS.code.stroke });
    // Weight matrix (large)
    drawWeight(gs, CX + 120, rowY, 'W_codes', `[${dModel}, ${fmtNum(vocabSize)}]`, COLORS.weight.fill, COLORS.weight.stroke, 180, WEIGHT_H);
    drawArrow(gs as Sel, CX - 80 + 20, rowY, CX + 120 - 90 - 4, rowY, { color: COLORS.code.stroke });

    // Output
    const outY = rowY + MAT_H / 2 + ROW_GAP + MAT_H / 2;
    arrowDown(gs, CX, rowY + MAT_H / 2, outY - MAT_H / 2, COLORS.code.stroke);
    drawSeqMatrix(gs, CX, outY, 'codes', `[${nPatches}, ${fmtNum(vocabSize)}]`, COLORS.code.fill, COLORS.code.stroke, 240, MAT_H);
    drawShapeEq(gs, CX, outY + MAT_H / 2 + 24, `patches [${nPatches}, ${dModel}] · W_codes [${dModel}, ${fmtNum(vocabSize)}] → codes [${nPatches}, ${fmtNum(vocabSize)}]`, COLORS.code.stroke);

    const codeParams = dModel * vocabSize;
    lbl(gs, CX + 120, rowY + WEIGHT_H / 2 + 14, `${fmtNum(codeParams)} params`, { size: 8, color: COLORS.muted });

    steps.push(makeStep(stepId, 'Codes', 'Code Logits', `patches · W_codes`, 'Linear projection maps each patch embedding to a score vector over the visual vocabulary.', 'step-code', COLORS.code.stroke, COLORS.code.fill, [
      `# Code logits: project to vocabulary space`,
      `W_codes = nn.Linear(${dModel}, ${vocabSize})`,
      `codes = W_codes(patches)  # [B, ${nPatches}, ${fmtNum(vocabSize)}]`,
    ]));
    stepId++;
    y = outY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 4: Quantize (Argmax) ─────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-quant', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Quantize (Argmax)', `discrete = argmax(codes, dim=-1) → [${nPatches}]`, COLORS.quant.fill, COLORS.quant.stroke);
    arrowDown(gs, CX, y, h, COLORS.quant.stroke);

    const rowY = h + BOX_TO_ROW + 30;
    // Softmax + argmax visualization
    // Show a single patch's score distribution → selected code
    const distW = 280;
    const distH = 80;
    const distX = CX - 160;
    const distG = gs.append('g').attr('transform', `translate(${distX - distW / 2}, ${rowY - distH / 2})`);
    distG.append('rect').attr('width', distW).attr('height', distH).attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', COLORS.code.stroke).attr('stroke-width', 0.5);
    lbl(gs, distX, rowY - distH / 2 - 10, 'patch_i score distribution', { size: 8, color: COLORS.muted });

    // Bar chart
    let seed3 = 321;
    const lcg3 = () => { seed3 = (seed3 * 1664525 + 1013904223) & 0xffffffff; return (seed3 >>> 0) / 0xffffffff; };
    const nBars = 16;
    const barW = (distW - 20) / nBars;
    let maxIdx = 0;
    let maxVal = 0;
    const vals: number[] = [];
    for (let i = 0; i < nBars; i++) {
      const v = lcg3();
      vals.push(v);
      if (v > maxVal) { maxVal = v; maxIdx = i; }
    }
    for (let i = 0; i < nBars; i++) {
      const barH = (vals[i] / maxVal) * (distH - 20);
      const isMax = i === maxIdx;
      distG.append('rect')
        .attr('x', 10 + i * barW + 1)
        .attr('y', distH - 10 - barH)
        .attr('width', barW - 2)
        .attr('height', barH)
        .attr('rx', 1)
        .attr('fill', isMax ? COLORS.quant.stroke : COLORS.code.stroke)
        .attr('opacity', isMax ? 0.9 : 0.3);
    }
    // Arrow pointing to max
    const maxX = 10 + maxIdx * barW + barW / 2;
    lbl(gs, distX - distW / 2 + maxX, rowY - distH / 2 + 4, '▼ argmax', { size: 7, color: COLORS.quant.stroke, weight: '700' });

    // Arrow to discrete code
    drawArrow(gs as Sel, distX + distW / 2 + 4, rowY, CX + 120, rowY, { color: COLORS.quant.stroke });
    lbl(gs, CX + 20, rowY - 14, 'select top-1', { size: 8, color: COLORS.muted });

    // Selected code badge
    const badgeW = 80;
    const badgeH = 50;
    gs.append('rect').attr('x', CX + 120 - badgeW / 2).attr('y', rowY - badgeH / 2).attr('width', badgeW).attr('height', badgeH).attr('rx', 8).attr('fill', COLORS.quant.fill).attr('stroke', COLORS.quant.stroke).attr('stroke-width', 2);
    lbl(gs, CX + 120, rowY - 6, `code`, { size: 8, color: COLORS.muted });
    lbl(gs, CX + 120, rowY + 10, `${Math.floor(maxIdx * vocabSize / nBars)}`, { size: 14, weight: '700', color: COLORS.quant.stroke });

    // Full code strip
    const stripY = rowY + distH / 2 + ROW_GAP;
    drawCodeStrip(gs, CX, stripY, nPatches, vocabSize, COLORS.quant.stroke);

    drawShapeEq(gs, CX, stripY + 36, `argmax over ${fmtNum(vocabSize)} logits → ${nPatches} integer codes`, COLORS.quant.stroke);

    steps.push(makeStep(stepId, 'Quantize', 'Quantize (Argmax)', `argmax(codes) → [${nPatches}]`, 'Select the highest-scoring code for each patch. This discretizes continuous embeddings into vocabulary indices.', 'step-quant', COLORS.quant.stroke, COLORS.quant.fill, [
      `# Quantize: select nearest code`,
      `discrete = codes.argmax(dim=-1)  # [B, ${nPatches}]`,
      `# Each value is an integer in [0, ${vocabSize})`,
    ]));
    stepId++;
    y = stripY + 36 + STEP_GAP;
  }

  // ── Step 5: Codebook Embedding Lookup ─────────────────────────────────────
  {
    const gs = startGroup(g, 'step-book', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Codebook Lookup', `tokens = Embed(discrete) → [${nPatches}, ${dModel}]`, COLORS.book.fill, COLORS.book.stroke);
    arrowDown(gs, CX, y, h, COLORS.book.stroke);

    // Discrete codes strip (input)
    const stripY = h + BOX_TO_ROW;
    drawCodeStrip(gs, CX - 240, stripY, nPatches, vocabSize, COLORS.quant.stroke);
    lbl(gs, CX - 240, stripY + 36, 'discrete codes', { size: 8, color: COLORS.muted });

    // Arrow to codebook
    drawArrow(gs as Sel, CX - 240 + 150 + 4, stripY, CX + 60 - 190 - 4, stripY, { color: COLORS.book.stroke });
    lbl(gs, CX - 80, stripY - 14, 'lookup', { size: 9, color: COLORS.book.stroke, weight: '600' });

    // Codebook
    const bookCY = stripY + ROW_GAP + 80;
    drawCodebook(gs, CX, bookCY, vocabSize, dModel, nPatches, COLORS.book.stroke);

    // Output matrix
    const outY = bookCY + 80 + ROW_GAP + MAT_H / 2;
    arrowDown(gs, CX, bookCY + 80, outY - MAT_H / 2, COLORS.book.stroke);
    drawSeqMatrix(gs, CX, outY, 'tokens', `[${nPatches}, ${dModel}]`, COLORS.book.fill, COLORS.book.stroke);
    drawShapeEq(gs, CX, outY + MAT_H / 2 + 24, `Embed [${fmtNum(vocabSize)}, ${dModel}][discrete] → tokens [${nPatches}, ${dModel}]`, COLORS.book.stroke);

    const bookParams = vocabSize * dModel;
    lbl(gs, CX + 200, bookCY, `${fmtNum(bookParams)} params`, { size: 8, color: COLORS.muted });

    steps.push(makeStep(stepId, 'Codebook', 'Codebook Lookup', `Embed[discrete] → [${nPatches}, ${dModel}]`, 'Look up each discrete code in the learned codebook embedding table to retrieve the corresponding dense vector.', 'step-book', COLORS.book.stroke, COLORS.book.fill, [
      `# Codebook lookup`,
      `codebook = nn.Embedding(${vocabSize}, ${dModel})`,
      `tokens = codebook(discrete)  # [B, ${nPatches}, ${dModel}]`,
    ]));
    stepId++;
    y = outY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 6: Output ────────────────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-out', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Output Visual Tokens', `tokens: [${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke);
    arrowDown(gs, CX, y, h, COLORS.out.stroke);

    const rowY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMatrix(gs, CX, rowY, 'visual tokens', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 240, MAT_H);

    lbl(gs, CX, rowY + MAT_H / 2 + 20, `${nPatches} discrete visual tokens → decoder / language model`, { size: 9, color: COLORS.muted });

    steps.push(makeStep(stepId, 'Output', 'Output Visual Tokens', `[${nPatches}, ${dModel}]`, `Final visual token sequence: ${nPatches} tokens of dimension ${dModel}, ready for the decoder or language model.`, 'step-out', COLORS.out.stroke, COLORS.out.fill));
    y = rowY + MAT_H / 2 + 20 + 20;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Entry point
// ═══════════════════════════════════════════════════════════════════════════════

export function renderImageTokenizerDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const nPatches = Number(params.n_patches) || 256;
  const dModel = Number(params.d_model) || 512;
  const vocabSize = Number(params.vocab_size) || 8192;

  let y = 10;

  // Title
  lbl(g, CX, y + 14, 'Image Tokenizer (VQ-VAE)', { size: 18, weight: '700', color: 'var(--text)' });
  y += 36;
  lbl(g, CX, y + 8, 'Encode image patches into a discrete vocabulary of visual tokens', { size: 10, color: 'var(--text-muted)' });
  y += 28;

  // Param summary bar
  const codebookParams = vocabSize * dModel;
  const codeParams = dModel * vocabSize;
  const totalParams = codebookParams + codeParams;
  y = drawParamSummary(g, CX, y, [
    `patches: ${nPatches}`,
    `d_model: ${dModel}`,
    `vocab: ${fmtNum(vocabSize)}`,
    `codebook: ${fmtNum(codebookParams)}`,
    `total: ${fmtNum(totalParams)}`,
  ]);
  y += 24;

  const { steps, y: pipelineY } = renderPipeline(g, y, nPatches, dModel, vocabSize);
  y = pipelineY + 20;

  // Explanation
  y = drawExplanation(
    g as Sel,
    CX - (W - 160) / 2,
    y,
    W - 160,
    `The Image Tokenizer converts an image into a sequence of discrete visual tokens using a VQ-VAE style pipeline. ` +
      `A convolution with kernel and stride equal to the patch size splits the image into non-overlapping patches and projects them to d_model. ` +
      `A linear layer maps each patch to vocabulary logits, argmax quantization selects the nearest code, and a learned codebook embedding retrieves the final token vectors. ` +
      `This discretization enables efficient compression and generation of visual content.`,
    'insight'
  );
  y += 16;

  // Component links
  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'embedding', 'Embedding');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'quantization', 'Quantization');
  y += 72;

  // Code annotation
  const patchSize = 16;
  const gridN = Math.round(Math.sqrt(nPatches));
  drawCodeAnnotation(
    g as Sel,
    CX - (W - 160) / 2,
    y,
    W - 160,
    'Image Tokenizer (PyTorch)',
    [`VQ-VAE pipeline: ${nPatches} patches → ${fmtNum(vocabSize)}-word codebook → ${dModel}-dim tokens`],
    [
      `class ImageTokenizer(nn.Module):`,
      `    def __init__(self, d_model=${dModel}, vocab_size=${vocabSize}):`,
      `        self.patchify = nn.Conv2d(3, ${dModel}, 16, stride=16)`,
      `        self.code_proj = nn.Linear(${dModel}, ${vocabSize})`,
      `        self.codebook = nn.Embedding(${vocabSize}, ${dModel})`,
      ``,
      `    def forward(self, image):  # [B, 3, ${patchSize * gridN}, ${patchSize * gridN}]`,
      `        patches = self.patchify(image)         # [B, ${dModel}, ${gridN}, ${gridN}]`,
      `        patches = patches.flatten(2).transpose(1,2) # [B, ${nPatches}, ${dModel}]`,
      `        codes = self.code_proj(patches)        # [B, ${nPatches}, ${vocabSize}]`,
      `        discrete = codes.argmax(dim=-1)        # [B, ${nPatches}]`,
      `        tokens = self.codebook(discrete)       # [B, ${nPatches}, ${dModel}]`,
      `        return tokens`,
    ]
  );

  return { width: W, height: y, steps };
}
